import{_ as a,c as n,a0 as i,o as s}from"./chunks/framework.BGabeMLJ.js";const p=JSON.parse('{"title":"FAQs as Administrator. Hub Management","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faqs/faqs-of-hub-management.md","filePath":"guide/faqs/faqs-of-hub-management.md"}'),r={name:"guide/faqs/faqs-of-hub-management.md"};function o(t,e,d,m,l,h){return s(),n("div",null,e[0]||(e[0]=[i('<h1 id="faqs-as-administrator-hub-management" tabindex="-1">FAQs as Administrator. Hub Management <a class="header-anchor" href="#faqs-as-administrator-hub-management" aria-label="Permalink to &quot;FAQs as Administrator. Hub Management&quot;">​</a></h1><h3 id="what-are-the-main-responsibilities-of-a-hub-administrator" tabindex="-1">What are the main responsibilities of a Hub administrator? <a class="header-anchor" href="#what-are-the-main-responsibilities-of-a-hub-administrator" aria-label="Permalink to &quot;What are the main responsibilities of a Hub administrator?&quot;">​</a></h3><p>A Hub Administrator manages the entire FLAME platform, overseeing infrastructure, organizations, authentication, node management, registry, project oversight, and user support. For detailed responsibilities, refer to <a href="/getting-started/components.html">Components in Hub</a>.</p><h3 id="how-do-i-manage-realms" tabindex="-1">How do I manage Realms? <a class="header-anchor" href="#how-do-i-manage-realms" aria-label="Permalink to &quot;How do I manage Realms?&quot;">​</a></h3><p>Realms are organizational namespaces managed by Hub administrators. Key actions include creating, providing initial realms, and monitoring activities. For more details, refer to <a href="/guide/admin/realms.html">Realm Management</a>.</p><h3 id="how-do-i-manage-users-and-roles" tabindex="-1">How do I manage users and roles? <a class="header-anchor" href="#how-do-i-manage-users-and-roles" aria-label="Permalink to &quot;How do I manage users and roles?&quot;">​</a></h3><p>Manage users and roles through the <strong>Admin area</strong>. View, add, edit, assign roles/permissions, and delete users or roles as needed. For detailed steps, see <a href="/guide/admin/users.html">User Management</a> and <a href="/guide/admin/roles.html">Role Management</a>.</p><h3 id="how-do-i-set-up-and-manage-identity-providers" tabindex="-1">How do I set up and manage identity providers? <a class="header-anchor" href="#how-do-i-set-up-and-manage-identity-providers" aria-label="Permalink to &quot;How do I set up and manage identity providers?&quot;">​</a></h3><p>Identity providers authenticate users externally.</p><p>Set up by navigating to Admin area → Auth → Identity Providers, adding configurations like Client ID, Secret, and endpoints. For detailed setup, refer to <a href="/guide/admin/identity-providers.html">Identity Providers</a>.</p><h3 id="how-do-i-view-and-assign-permissions" tabindex="-1">How do I view and assign permissions? <a class="header-anchor" href="#how-do-i-view-and-assign-permissions" aria-label="Permalink to &quot;How do I view and assign permissions?&quot;">​</a></h3><p>View and assign permissions in the Admin area under Permissions and Roles tabs. Assign roles to users to grant specific permissions. For more information, see <a href="/guide/admin/permissions.html">Permissions and Roles</a>.</p><h3 id="how-do-i-review-and-approve-analyses" tabindex="-1">How do I review and approve analyses? <a class="header-anchor" href="#how-do-i-review-and-approve-analyses" aria-label="Permalink to &quot;How do I review and approve analyses?&quot;">​</a></h3><p>Hub administrators review analysis code for safety and protocol adherence. Navigate to Home → Analyses → Incoming, download, review, and approve or reject analyses. For detailed steps, refer to <a href="/guide/admin/analysis-review.html">Analysis Review</a>.</p><h3 id="how-do-i-register-and-manage-local-nodes" tabindex="-1">How do I register and manage local nodes? <a class="header-anchor" href="#how-do-i-register-and-manage-local-nodes" aria-label="Permalink to &quot;How do I register and manage local nodes?&quot;">​</a></h3><p>Register nodes in the Admin area under General → Nodes. Fill in required information, generate credentials, and deploy locally. Manage node settings and credentials as needed. For more details, see <a href="/guide/deployment/node-registration.html">Node Registration</a> in the deployment part and <a href="/guide/admin/node-management.html">Node Management</a>.</p>',16)]))}const u=a(r,[["render",o]]);export{p as __pageData,u as default};
